import { lccaGroExamsB } from './lccaExamsGroB';
import { lccaGroExamsC } from './lccaExamsGroC';

export type ExamQuestion = {
  id: string;
  domain: string;
  question: string;
  options: string[];
  correct: number;
  explanation: string;
};

export type PracticeExam = {
  id: string;
  number: number;
  title: string;
  description: string;
  questions: ExamQuestion[];
};

// Exams 9-11: Chapter 748 mastery exams. Exams 1-8 live in lccaExamsGro{A,B,C}.ts.
const lccaExams9to11: PracticeExam[] = [
  {
    id: 'exam-9',
    number: 9,
    title: 'Chapter 748 Mastery Exam',
    description: '53 questions drawn directly from 26 TAC Chapter 748 — Minimum Standards for General Residential Operations. Timelines, ratios, service plans, reporting, medication, and child rights. This is the core of the LCCA exam.',
    questions: [
      { id: 'e9q1', domain: 'Chapter 748', question: 'Under §748.1331, a preliminary service plan must be completed within:', options: ['24 hours of admission', '48 hours of admission', '72 hours of admission', '7 days of admission'], correct: 2, explanation: 'The preliminary service plan must be completed within 72 hours of admission to address the child\'s immediate needs such as supervision, school enrollment, and medical care.' },
      { id: 'e9q2', domain: 'Chapter 748', question: 'Under §748.1335, an initial service plan must be completed within:', options: ['30 days of admission', '40 days of admission', '45 days of admission', '60 days of admission'], correct: 2, explanation: 'The initial service plan must be completed within 45 days of admission under §748.1335.' },
      { id: 'e9q3', domain: 'Chapter 748', question: 'For a child receiving child-care services (not treatment services), the service plan must be reviewed at least every:', options: ['45 days', '90 days', '120 days', '180 days'], correct: 3, explanation: 'Service plans for children receiving child-care services must be reviewed at least every 180 days under §748.1381.' },
      { id: 'e9q4', domain: 'Chapter 748', question: 'For a child receiving treatment services for an emotional disorder, the service plan must be reviewed at least every:', options: ['45 days', '60 days', '90 days', '180 days'], correct: 2, explanation: 'Service plans for children receiving treatment services for emotional disorders, autism spectrum disorder, or primary medical needs must be reviewed at least every 90 days.' },
      { id: 'e9q5', domain: 'Chapter 748', question: 'A service plan must be implemented no later than how many days after the scheduled service planning meeting?', options: ['7 days', '10 days', '15 days', '30 days'], correct: 2, explanation: 'Under §748.1351, a service plan must be implemented no later than 15 days after the date of the scheduled service planning meeting involving the parents and the child.' },
      { id: 'e9q6', domain: 'Chapter 748', question: 'Parents must receive advance notice of an initial service plan meeting at least:', options: ['3 days before', '1 week before', '2 weeks before', '30 days before'], correct: 2, explanation: 'Under §748.1341, the child\'s parent must have at least two weeks advance notice of the initial service plan meeting.' },
      { id: 'e9q7', domain: 'Chapter 748', question: 'The service planning team for a child receiving child-care services must include at minimum:', options: ['Only the administrator and a caregiver', 'At least 1 caregiver, 1 designated person for childhood activities, and 1 professional level service provider', 'A psychiatrist and a social worker', 'The child\'s parents and a caseworker'], correct: 1, explanation: 'Under §748.1339, the service planning team must include at least 1 current caregiver, a person designated to make decisions about childhood activities, and at least 1 professional level service provider.' },
      { id: 'e9q8', domain: 'Chapter 748', question: 'For a child receiving treatment services for intellectual disabilities, the service plan must be reviewed at least every 180 days during the first year, and thereafter:', options: ['Every 90 days', 'Every 180 days', 'Annually', 'Every 2 years'], correct: 2, explanation: 'Under §748.1381, for intellectual disabilities, the plan must be reviewed at least every 180 days in the first year, then at least annually thereafter.' },
      { id: 'e9q9', domain: 'Chapter 748', question: 'For an emergency admission, all requirements for the admission assessment must be completed within:', options: ['24 hours', '72 hours', '30 days', '40 days'], correct: 3, explanation: 'Under §748.1269, for an emergency admission, all requirements for the admission assessment must be completed within 40 days from the date of the child\'s admission.' },
      { id: 'e9q10', domain: 'Chapter 748', question: 'For a child receiving treatment services admitted on an emergency basis to a GRO (not RTC), the child may not continue in care for more than how many days without the required psychiatric/psychological evaluation?', options: ['10 days', '20 days', '30 days', '40 days'], correct: 2, explanation: 'Under §748.1269, a child receiving treatment services may not continue in care for more than 30 days after admission (or 10 days for an RTC) without the required evaluation.' },
      { id: 'e9q11', domain: 'Chapter 748', question: 'During waking hours in a GRO, if at least one child in the group requires treatment services, the required ratio is:', options: ['1:4', '1:5', '1:8', '1:10'], correct: 1, explanation: 'Under §748.1003, when at least one child requires treatment services, the waking ratio is 1:5. If no children require treatment services, the ratio is 1:8.' },
      { id: 'e9q12', domain: 'Chapter 748', question: 'During waking hours in a GRO, if NO children in the group require treatment services, the required ratio is:', options: ['1:5', '1:8', '1:10', '1:15'], correct: 1, explanation: 'Under §748.1003, when no children require treatment services, the waking ratio is 1:8.' },
      { id: 'e9q13', domain: 'Chapter 748', question: 'In a GRO, children under 5 years old count as how many children for ratio purposes?', options: ['1 child', '2 children', '3 children', 'They are not counted'], correct: 1, explanation: 'Under §748.1003, children younger than 5 years old count as 2 children for ratio calculation purposes — both during waking hours and nighttime sleeping hours.' },
      { id: 'e9q14', domain: 'Chapter 748', question: 'At night when the caregiver stays AWAKE and at least one child requires treatment services, the ratio is:', options: ['1:5', '1:10', '1:15', '1:16'], correct: 2, explanation: 'Under §748.1007(b), when the caregiver stays awake at night, one caregiver may care for 15 children if at least one child in the group requires treatment services, or 24 children if none do. Children younger than 5 count as two children. (If the caregiver sleeps, the ratios drop to 1:10 with treatment services and 1:16 without — §748.1007(c).)' },
      { id: 'e9q15', domain: 'Chapter 748', question: 'At night when the caregiver SLEEPS and at least one child requires treatment services, the ratio is:', options: ['1:5', '1:10', '1:15', '1:16'], correct: 1, explanation: 'Under §748.1007(c), when the caregiver sleeps at night, one caregiver may care for 10 children if at least one child in the group requires treatment services, or 16 children if none do. Children younger than 5 count as two children. (If the caregiver stays awake: 1:15 with treatment services, 1:24 without — §748.1007(b).)' },
      { id: 'e9q16', domain: 'Chapter 748', question: 'At night when the caregiver SLEEPS and NO children require treatment services, the ratio is:', options: ['1:8', '1:10', '1:16', '1:24'], correct: 2, explanation: 'Under §748.1007, when the caregiver sleeps at night and no children require treatment services, the ratio is 1:16.' },
      { id: 'e9q17', domain: 'Chapter 748', question: 'A caregiver who is working in an administrative capacity at the time may be counted in the child/caregiver ratio:', options: ['Yes, always', 'Yes, if they are on the same floor', 'No — a person in an administrative capacity cannot be counted in ratio', 'Only if they are the administrator'], correct: 2, explanation: 'Under §748.1005, a person may not be counted in the ratio for a group of children if they are working in an administrative capacity or caring for children outside the group.' },
      { id: 'e9q18', domain: 'Chapter 748', question: 'When a child dies while in your care, you must report to law enforcement within:', options: ['30 minutes', '1 hour', '2 hours', '24 hours'], correct: 1, explanation: 'Under §748.303, a child death must be reported to law enforcement immediately, but no later than 1 hour after the child\'s death.' },
      { id: 'e9q19', domain: 'Chapter 748', question: 'When a child dies while in your care, you must report to Licensing and parents within:', options: ['1 hour', '2 hours', '4 hours', '24 hours'], correct: 1, explanation: 'Under §748.303, a child death must be reported to Licensing and parents as soon as possible, but no later than 2 hours after the child\'s death.' },
      { id: 'e9q20', domain: 'Chapter 748', question: 'A child sustains a substantial physical injury. You must report to Licensing within:', options: ['1 hour', '2 hours', '12 hours', '24 hours'], correct: 3, explanation: 'Under §748.303, a substantial physical injury must be reported to Licensing as soon as possible, but no later than 24 hours after the incident.' },
      { id: 'e9q21', domain: 'Chapter 748', question: 'A 4-year-old is discovered missing from your GRO. You must report to law enforcement:', options: ['Within 1 hour', 'Within 2 hours', 'Immediately upon determining the child is not on the premises and is still missing', 'Within 6 hours'], correct: 2, explanation: 'Under §748.303, for an unauthorized absence of a child under 6, you must notify law enforcement immediately upon determining the child is not on the premises and is still missing.' },
      { id: 'e9q22', domain: 'Chapter 748', question: 'A 4-year-old is missing. After notifying law enforcement, you must report to Licensing and parents within:', options: ['30 minutes', '1 hour', '2 hours', '6 hours'], correct: 2, explanation: 'Under §748.303, for a child under 6, you must report to Licensing and parents within 2 hours of notifying law enforcement.' },
      { id: 'e9q23', domain: 'Chapter 748', question: 'A 15-year-old leaves your GRO without permission and is still missing. When must you report to Licensing?', options: ['Immediately when discovered', 'Within 2 hours of discovery', 'No later than 6 hours from when the absence was discovered', 'Within 24 hours'], correct: 2, explanation: 'Under §748.303, for a child 13 or older, you must report to all parties no later than 6 hours from when the child\'s absence is discovered and the child is still missing.' },
      { id: 'e9q24', domain: 'Chapter 748', question: 'A 15-year-old who was previously identified as a trafficking victim leaves without permission. When must you report?', options: ['Within 6 hours', 'Within 2 hours', 'Immediately', 'Within 24 hours'], correct: 2, explanation: 'Under §748.303, if the child has previously been alleged or determined to be a trafficking victim, you must report the absence IMMEDIATELY — not within the standard 6-hour window.' },
      { id: 'e9q25', domain: 'Chapter 748', question: 'A child in your GRO attempts suicide. You must report to Licensing:', options: ['Within 1 hour', 'Within 2 hours', 'As soon as you become aware of the incident', 'Within 24 hours'], correct: 2, explanation: 'Under §748.303, a suicide attempt must be reported to Licensing as soon as you become aware of the incident.' },
      { id: 'e9q26', domain: 'Chapter 748', question: 'After a child returns from an unauthorized absence, you must debrief the child within:', options: ['2 hours of return', '12 hours of return', '24 hours of return', '48 hours of return'], correct: 2, explanation: 'Under §748.455, the debriefing must occur as soon as possible, but no later than 24 hours after the child\'s return.' },
      { id: 'e9q27', domain: 'Chapter 748', question: 'If a child has 3 unauthorized absences within a 60-day timeframe, a triggered review must occur within:', options: ['7 days', '14 days', '30 days', '60 days'], correct: 2, explanation: 'Under §748.457, a triggered review must occur as soon as possible, but no later than 30 days after the child\'s third unauthorized absence within a 60-day timeframe.' },
      { id: 'e9q28', domain: 'Chapter 748', question: 'An overall operation evaluation for unauthorized absences must be conducted every:', options: ['3 months', '6 months', '12 months', '2 years'], correct: 1, explanation: 'Under §748.463, every 6 months you must conduct an overall operation evaluation for unauthorized absences that have occurred at your operation during that time period.' },
      { id: 'e9q29', domain: 'Chapter 748', question: 'All serious incident reports must be made directly to:', options: ['Your CCR licensing representative', 'The Texas Abuse and Neglect Hotline', 'The local police department', 'The DFPS regional office'], correct: 1, explanation: 'Under §748.309, all serious incident reports must be made directly to the Texas Abuse and Neglect Hotline.' },
      { id: 'e9q30', domain: 'Chapter 748', question: 'A child-care administrator under Chapter 748 must be:', options: ['A part-time employee with an LCCA license', 'A full-time employee with an LCCA license', 'A full-time employee with a master\'s degree', 'Any licensed professional designated by the governing body'], correct: 1, explanation: 'Under §748.531, a child-care administrator must be a Licensed Child-Care Administrator AND a full-time employee of the operation.' },
      { id: 'e9q31', domain: 'Chapter 748', question: 'You must notify Licensing when your child-care administrator position becomes vacant within:', options: ['24 hours', '2 days', '7 days', '15 days'], correct: 1, explanation: 'Under §748.153, you must notify Licensing as soon as possible, but no later than 2 days after your child-care administrator changes or the position becomes vacant.' },
      { id: 'e9q32', domain: 'Chapter 748', question: 'If your administrator position becomes vacant and you have NO backup administrator, you have how long to obtain a licensed administrator before CCR can cite you?', options: ['30 days', '45 days', '60 days', '90 days'], correct: 2, explanation: 'Under §748.154, if there is no backup administrator, you have 60 days from the date the position becomes vacant to obtain a licensed child-care administrator before CCR can cite you.' },
      { id: 'e9q33', domain: 'Chapter 748', question: 'When the administrator is absent on a frequent and/or extended basis, the backup must be:', options: ['Any senior staff member', 'A person with a Child-Care Administrator\'s License', 'A professional level service provider', 'The treatment director'], correct: 1, explanation: 'Under §748.539, when the administrator is absent frequently or for an extended period, the designated backup must have a Child-Care Administrator\'s License.' },
      { id: 'e9q34', domain: 'Chapter 748', question: 'A caregiver must be at least 21 years old if:', options: ['They work in a residential treatment center', 'At least one child in the group they serve is 13 years old or older', 'They administer medication', 'They are the only caregiver on duty'], correct: 1, explanation: 'Under §748.681, a caregiver must be at least 21 years old if at least one child in the group they serve is 13 years old or older. If all children are under 13, the minimum age is 18.' },
      { id: 'e9q35', domain: 'Chapter 748', question: 'How many hours of general pre-service training must a caregiver complete before being counted in the child/caregiver ratio?', options: ['2 hours', '4 hours', '8 hours', '16 hours'], correct: 1, explanation: 'Under §748.863, a caregiver must complete at least 4 hours of general pre-service training before being counted in the ratio. The remaining 4 hours (total 8) must be completed within 30 days.' },
      { id: 'e9q36', domain: 'Chapter 748', question: 'A caregiver at a GRO with 25 or more children receiving treatment services must complete how many annual training hours?', options: ['20 hours', '30 hours', '40 hours', '50 hours'], correct: 3, explanation: 'Under §748.930, caregivers at operations with 25 or more children receiving treatment services (or 30% or more of the population) must complete 50 hours of annual training.' },
      { id: 'e9q37', domain: 'Chapter 748', question: 'A caregiver at a GRO with fewer than 25 treatment services children must complete how many annual training hours?', options: ['10 hours', '15 hours', '20 hours', '30 hours'], correct: 2, explanation: 'Under §748.930, caregivers at operations with less than 25 children receiving treatment services (and less than 30% of the population) must complete 20 hours of annual training.' },
      { id: 'e9q38', domain: 'Chapter 748', question: 'Emergency Behavior Intervention (EBI) annual training for caregivers at treatment operations must be completed every:', options: ['3 months', '6 months', '12 months', '2 years'], correct: 1, explanation: 'Under §748.936, caregivers at operations providing treatment services must complete EBI training every 6 months.' },
      { id: 'e9q39', domain: 'Chapter 748', question: 'The maximum number of annual training hours that may come from self-study training is:', options: ['1 hour', '3 hours', '5 hours', '10 hours'], correct: 1, explanation: 'Under §748.937, no more than 3 hours of the required annual training hours may come from self-study training (non-standardized reading, watching videos, etc.).' },
      { id: 'e9q40', domain: 'Chapter 748', question: 'Personnel records must be maintained for how long after an employee\'s last day of employment?', options: ['6 months', '1 year (or until investigation resolved)', '2 years', '3 years'], correct: 1, explanation: 'Under §748.431, personnel records must be maintained for 1 year after an employee\'s last day of employment, or until any investigation involving the employee is resolved, whichever is longer.' },
      { id: 'e9q41', domain: 'Chapter 748', question: 'Schedule II controlled substances must be stored under:', options: ['A single lock', 'Double lock in a separate container', 'A locked refrigerator', 'The administrator\'s personal custody'], correct: 1, explanation: 'Under §748.2101, Schedule II controlled substances must be stored under double lock in a separate container — for example, a lock on the cabinet AND a lock on the closet door.' },
      { id: 'e9q42', domain: 'Chapter 748', question: 'A medication administration record must be updated within how long of administering medication (non-cottage home)?', options: ['30 minutes', '1 hour', '2 hours', '24 hours'], correct: 2, explanation: 'Under §748.2151, the cumulative medication record must be updated within 2 hours of administering medication (or within 24 hours for cottage homes).' },
      { id: 'e9q43', domain: 'Chapter 748', question: 'Prescription medication must be administered within how long of preparation?', options: ['30 minutes', '1 hour', '2 hours', '4 hours'], correct: 1, explanation: 'Under §748.2003, each child\'s medication must be administered within 1 hour of preparation.' },
      { id: 'e9q44', domain: 'Chapter 748', question: 'If a prescribing professional does not substantiate the effectiveness of a psychotropic medication within 90 days, the continuation may not exceed an additional:', options: ['30 days', '60 days', '90 days', '180 days'], correct: 2, explanation: 'Under §748.2261, if effectiveness is not substantiated within 90 days, the professional must provide written rationale, and continuation may not exceed an additional 90 days (total 180 days).' },
      { id: 'e9q45', domain: 'Chapter 748', question: 'A medication error must be documented within:', options: ['1 hour', '2 hours', '12 hours', '24 hours'], correct: 3, explanation: 'Under §748.2203, all medication errors must be documented within 24 hours, including the time/date of the error, the error itself, and the health-care professional\'s recommendations.' },
      { id: 'e9q46', domain: 'Chapter 748', question: 'Which of the following is a PROHIBITED discipline technique under Chapter 748?', options: ['Brief supervised separation from the group', 'Logical consequences related to the behavior', 'Denying food as punishment', 'Verbal redirection'], correct: 2, explanation: 'Under §748.2307, denying food that meets the child\'s nutritional requirements is a prohibited discipline technique. This is a High Weight violation.' },
      { id: 'e9q47', domain: 'Chapter 748', question: 'Which of the following techniques is ABSOLUTELY PROHIBITED under Chapter 748 and may NEVER be used on any child?', options: ['Brief personal restraint', 'Seclusion for children with emotional disorders', 'Pressure points', 'Verbal de-escalation'], correct: 2, explanation: 'Under §748.1119, pressure points are absolutely prohibited and may never be used on any child. Other prohibited techniques include chemical restraints, aversive conditioning, rebirthing therapy, hug/holding therapy, and tasers.' },
      { id: 'e9q48', domain: 'Chapter 748', question: 'If you restrict a child\'s contact with siblings and the restriction continues for more than 60 days, it must be re-evaluated every:', options: ['30 days', '60 days', '90 days', '180 days'], correct: 1, explanation: 'Under §748.1109, restrictions on sibling contact that continue for more than 60 days must be re-evaluated every 60 days by a professional level service provider.' },
      { id: 'e9q49', domain: 'Chapter 748', question: 'An operation licensed to provide emergency care services may temporarily exceed its licensed capacity for no more than how long to care for a child needing emergency care?', options: ['24 hours', '48 hours', '72 hours', '7 days'], correct: 1, explanation: 'Under §748.155(b), an operation licensed for emergency care services may temporarily exceed its licensed capacity for not more than 48 hours. Under §748.153(4), you must also notify your Licensing Representative within 24 hours of the child\'s placement when you exceed capacity this way.' },
      { id: 'e9q50', domain: 'Chapter 748', question: 'A 15-year-old leaves without permission but returns before the 6-hour reporting timeframe elapses. What must the GRO do?', options: ['Report it to the Hotline anyway within 24 hours', 'Nothing — no documentation is needed', 'No serious incident report is required, but document the absence within 24 hours after becoming aware of it, the same way as a serious incident', 'Report only to the parents'], correct: 2, explanation: 'Under §748.303(c), if the child returns before the required reporting timeframe, the GRO is not required to report the absence as a serious incident. It must instead document it within 24 hours after becoming aware of the absence, in the same manner as a serious incident (§748.311).' },
      { id: 'e9q51', domain: 'Chapter 748', question: 'You plan to change your operation\'s operating hours. When must you give your Licensing Representative written notice?', options: ['Within 2 days after the change', 'As soon as possible, but at least 15 days before', 'As soon as possible, but at least 30 days before', 'Within 24 hours before'], correct: 2, explanation: 'Under §748.153(1), written notice is due as soon as possible, but at least 30 days before you change the legal structure or governing body, move the operation, or change your operating hours. Changes to required policies and procedures, the floor plan, or starting construction of a swimming pool require at least 15 days\' notice (§748.153(2)).' },
      { id: 'e9q52', domain: 'Chapter 748', question: 'Unless there is an acceptable reason not to have it, a GRO must maintain liability insurance of at least how much per occurrence of negligence, with proof provided to Licensing each year?', options: ['$100,000', '$300,000', '$500,000', '$1,000,000'], correct: 1, explanation: 'Under §748.158, you must maintain liability insurance of $300,000 for each occurrence of negligence covering injury to a child on your premises or in your care, and provide proof of coverage to Licensing each year by the anniversary date of the permit\'s issuance.' },
      { id: 'e9q53', domain: 'Chapter 748', question: 'How long must a GRO keep serious incident reports on file at the operation, easily accessible to Licensing?', options: ['1 year', '2 years', '3 years', '5 years'], correct: 1, explanation: 'Under §748.315, incident reports must be kept on file for two years. By comparison, a child\'s record must be kept two years after discharge or until any investigation is resolved, whichever is longer (§748.433), and the results of each six-month unauthorized-absence evaluation must be kept five years (§748.463(d)).' },
    ],
  },
  {
    id: 'exam-10',
    number: 10,
    title: 'Ch. 748 — Environment, Transport & EBI',
    description: '54 questions covering Chapter 748 physical environment, transportation, Emergency Behavior Intervention, prohibited techniques, normalcy, and the Reasonable and Prudent Parent Standard.',
    questions: [
      { id: 'e10q1', domain: 'Chapter 748', question: 'The minimum floor space required per occupant in a shared bedroom under Chapter 748 is:', options: ['40 sq ft', '50 sq ft', '60 sq ft', '80 sq ft'], correct: 2, explanation: 'Under §748.3357(b), a shared bedroom needs at least 60 sq ft of floor space per occupant (a single-occupancy bedroom needs at least 80 sq ft), with no more than four occupants per bedroom. Floor space may not be averaged.' },
      { id: 'e10q2', domain: 'Chapter 748', question: 'Children of the opposite gender may not share a bedroom (unless an exception applies) if they are at least:', options: ['3 years old', '5 years old', '6 years old', '12 years old'], correct: 2, explanation: '§748.3363(a): a child six years old or older must not share a bedroom with a child of the opposite gender unless they are siblings, the older child is the younger child\'s parent, or both are non-ambulatory and receive treatment services for primary medical needs. Even then the service planning team must assess and document (§748.3363(b)).' },
      { id: 'e10q3', domain: 'Chapter 748', question: 'The minimum number of toilets required per 8 children in a GRO is:', options: ['1', '2', '3', '4'], correct: 0, explanation: 'Chapter 748 requires a minimum of 1 toilet per 8 children, 1 sink per 8 children, and 1 bathtub or shower per 8 children.' },
      { id: 'e10q4', domain: 'Chapter 748', question: 'The maximum hot water temperature at fixtures used by children in a GRO is:', options: ['100°F', '110°F', '120°F', '130°F'], correct: 2, explanation: 'Chapter 748 requires that hot water temperature at fixtures used by children must not exceed 120°F to prevent scalding.' },
      { id: 'e10q5', domain: 'Chapter 748', question: 'Firearms and ammunition in a GRO must be stored:', options: ['In a single locked container together', 'In locked containers, separate from each other', 'In the administrator\'s office', 'Off-site at all times'], correct: 1, explanation: 'Under Chapter 748, all firearms and ammunition must be stored in locked containers, and they must be stored separately from each other.' },
      { id: 'e10q6', domain: 'Chapter 748', question: 'The minimum indoor activity space required per child (excluding sleeping areas and bathrooms) is:', options: ['20 sq ft', '30 sq ft', '40 sq ft', '60 sq ft'], correct: 2, explanation: 'Chapter 748 requires a minimum of 40 square feet of indoor activity space per child, excluding sleeping areas, bathrooms, and hallways.' },
      { id: 'e10q7', domain: 'Chapter 748', question: 'Does the child/caregiver ratio apply to field trips and appointments away from the operation?', options: ['No, only at the operation', 'Yes, it applies to activities away from the operation', 'Only for overnight trips', 'Only for children under 5'], correct: 1, explanation: '§748.1017(a): the child/caregiver ratio applies to activities sponsored or conducted by the operation, including field trips and appointments away from the operation. Additional caregivers may be needed for special needs such as a non-ambulatory child (§748.1017(b)).' },
      { id: 'e10q8', domain: 'Chapter 748', question: 'Children under what age (or height) must be in a child safety seat or booster seat during transport?', options: ['Under 6 years old or under 4 ft 6 in', 'Under 8 years old or under 4 ft 9 in', 'Under 10 years old or under 5 ft', 'Under 12 years old'], correct: 1, explanation: 'Children under 8 years old OR under 4 feet 9 inches tall must be in a child safety seat or booster seat during transport.' },
      { id: 'e10q9', domain: 'Chapter 748', question: 'Which of the following must be accessible in each vehicle used to transport children on an overnight trip?', options: ['A GPS tracking device', 'A first-aid kit, fire extinguisher, and operable flashlight', 'A two-way radio', 'A spare tire and phone charger'], correct: 1, explanation: '§748.4007 requires a first-aid kit, a fire extinguisher, and an operable flashlight in vehicles on overnight trips. You must also have a list of the children, emergency medical authorization forms, a medication list, the operation\'s name and phone number, and parent and emergency phone numbers for each child.' },
      { id: 'e10q10', domain: 'Chapter 748', question: 'A child under what age may NEVER be left unattended in a vehicle?', options: ['5', '6', '8', '12'], correct: 2, explanation: '§748.4011(3) (High weight): you must never leave a child under eight years old unattended in a vehicle. You must also account for all children exiting before leaving a vehicle unattended (§748.4011(1)), and a child under 8 must be accompanied by an adult when crossing a street (§748.4011(2)).' },
      { id: 'e10q11', domain: 'Chapter 748', question: 'Emergency Behavior Intervention (EBI) may ONLY be used when:', options: ['A child is non-compliant with staff instructions', 'A child\'s behavior poses an immediate danger to themselves or others', 'A child is being verbally aggressive', 'Staff need to move a child to a different location'], correct: 1, explanation: 'EBI may only be used when a child\'s behavior poses an immediate danger to themselves or others, and only after less restrictive interventions have been attempted or are not feasible.' },
      { id: 'e10q12', domain: 'Chapter 748', question: 'EBI must NEVER be used:', options: ['During waking hours', 'As punishment, retribution, or for caregiver convenience', 'Without a second staff member present', 'Both A and C'], correct: 1, explanation: '§748.2463: EBI may never be used as punishment, retribution or retaliation, a means to get a child to comply, a convenience for caregivers, or a substitute for effective treatment. (See also §748.2307.) A second caregiver should monitor only if one is available (§748.2601(b)).' },
      { id: 'e10q13', domain: 'Chapter 748', question: 'During any EBI, the child must be monitored:', options: ['Every 5 minutes', 'Every 15 minutes', 'Continuously', 'By a supervisor only'], correct: 2, explanation: 'The child must be monitored continuously during any EBI to ensure their safety and to discontinue the intervention as soon as the danger has passed.' },
      { id: 'e10q14', domain: 'Chapter 748', question: 'EBI must be documented within:', options: ['1 hour', '4 hours', '24 hours', '48 hours'], correct: 2, explanation: '§748.2855(a): document the intervention in the child\'s record as soon as possible, but no later than 24 hours after it was initiated. Written parent notice is a separate deadline of 72 hours (§748.2857). Short personal restraints are exempt from both.' },
      { id: 'e10q15', domain: 'Chapter 748', question: 'After an EBI, the child must be given an opportunity to discuss the situation in private:', options: ['Within 1 hour', 'Within 24 hours', 'As soon as possible, and no later than 48 hours after release', 'At the next scheduled therapy session'], correct: 2, explanation: '§748.2851(a)(3): the child must have an opportunity to discuss the situation in private as soon as possible and no later than 48 hours after release. Caregivers also debrief each other (§748.2851(c)), and the supervisor reviews the intervention within 72 hours (§748.2851(d)).' },
      { id: 'e10q16', domain: 'Chapter 748', question: 'Without a continuation order, the maximum length of a seclusion for a child under 9 years old is:', options: ['30 minutes', '1 hour', '2 hours', '4 hours'], correct: 1, explanation: '§748.2801(4): seclusion may not exceed one hour for a child under nine, or two hours for a child nine or older. A written continuation order from a qualified professional may extend it, but never beyond 4 hours (§748.2805, §748.2807(d)).' },
      { id: 'e10q17', domain: 'Chapter 748', question: 'A seclusion room must be at least how many square feet?', options: ['25 sq ft', '40 sq ft', '50 sq ft', '75 sq ft'], correct: 1, explanation: '§748.2651(b): a seclusion room must have at least 40 square feet of floor space and a ceiling height of at least eight feet, be free of hazards, and be properly lighted, ventilated and heated, with a mat and bedding unless ordered otherwise. Staff must continuously observe the child (§748.2651(a)); video is not a substitute.' },
      { id: 'e10q18', domain: 'Chapter 748', question: 'Which of the following is ABSOLUTELY PROHIBITED under Chapter 748 and may never be used on any child?', options: ['Brief personal restraint during a safety emergency', 'Aversive conditioning', 'Verbal de-escalation', 'Temporary seclusion for children over 6'], correct: 1, explanation: 'Aversive conditioning — using painful or unpleasant stimuli to change behavior — is absolutely prohibited under §748.1119 and may never be used on any child.' },
      { id: 'e10q19', domain: 'Chapter 748', question: 'Rebirthing therapy is:', options: ['An approved therapeutic technique for trauma', 'Absolutely prohibited under Chapter 748', 'Allowed only with parental consent', 'Allowed only by licensed therapists'], correct: 1, explanation: 'Rebirthing therapy — any technique that simulates the birth process — is absolutely prohibited under §748.1119 and may never be used on any child.' },
      { id: 'e10q20', domain: 'Chapter 748', question: 'Hug/holding therapy (forced holding for therapeutic purposes) is:', options: ['Allowed with parental consent', 'Allowed only by licensed therapists', 'Absolutely prohibited under Chapter 748', 'Allowed for children under 6 only'], correct: 2, explanation: 'Hug/holding therapy is absolutely prohibited under §748.1119 and may never be used on any child under any circumstances.' },
      { id: 'e10q21', domain: 'Chapter 748', question: 'Which of the following is a PROHIBITED DISCIPLINE technique under Chapter 748?', options: ['Brief supervised separation from the group', 'Logical consequences related to the behavior', 'Requiring a child to wear embarrassing clothing', 'Verbal redirection'], correct: 2, explanation: 'Requiring a child to wear embarrassing clothing is a prohibited discipline technique under §748.2307. It is intended to demean or embarrass the child.' },
      { id: 'e10q22', domain: 'Chapter 748', question: 'Threatening a child with loss of placement as a discipline technique is:', options: ['Allowed if the threat is not carried out', 'Prohibited under Chapter 748', 'Allowed only for serious behavioral issues', 'Allowed with supervisor approval'], correct: 1, explanation: 'Threatening loss of placement is a prohibited discipline technique under §748.2307. It creates fear and instability that can re-traumatize children.' },
      { id: 'e10q23', domain: 'Chapter 748', question: 'Unproductive work (moving rocks, digging holes) as punishment is:', options: ['Allowed as a natural consequence', 'Prohibited under Chapter 748', 'Allowed for children over 12', 'Allowed with parental consent'], correct: 1, explanation: 'Unproductive work as punishment is prohibited under §748.2303(b)(2) and §748.2305. This includes moving rocks, digging holes, running laps, or any other meaningless physical task used as punishment.' },
      { id: 'e10q24', domain: 'Chapter 748', question: 'The Reasonable and Prudent Parent Standard (RPPS) is designed to:', options: ['Restrict children from risky activities', 'Allow children to have normal childhood experiences by applying the standard a reasonable parent would use', 'Require caseworker approval for all activities', 'Limit activities to those in the service plan'], correct: 1, explanation: 'The RPPS is designed to allow children in care to have normal childhood experiences. It asks what a reasonable and prudent parent would allow for a child of this age and maturity.' },
      { id: 'e10q25', domain: 'Chapter 748', question: 'The name of each person designated to make Reasonable and Prudent Parent Standard decisions must be documented on:', options: ['The operation\'s policy manual', 'The face sheet of the child\'s record', 'The admission agreement', 'The governing body\'s bylaws'], correct: 1, explanation: '§748.709(c): the name of each designated person must be documented on the face sheet of the child\'s record. The designee must work where the child lives and know the child\'s needs and history (§748.709(b)), and restrictions go in the service plan (§748.703(b)).' },
      { id: 'e10q26', domain: 'Chapter 748', question: 'A 16-year-old in your GRO wants to get a part-time job at a local grocery store. Under the RPPS, you should:', options: ['Deny the request — employment creates too much risk', 'Apply the RPPS: would a reasonable parent allow a 16-year-old to work part-time? Yes — support the request', 'Require caseworker approval before considering the request', 'Allow it only if the service plan specifically addresses employment'], correct: 1, explanation: 'The RPPS asks what a reasonable parent would allow. A reasonable parent would generally support a 16-year-old getting a part-time job. The goal is to support normal development, not restrict it.' },
      { id: 'e10q27', domain: 'Chapter 748', question: 'Restrictions on normalcy activities must be:', options: ['Approved by the governing body', 'Documented and justified in the service plan', 'Approved by the child\'s caseworker only', 'Reviewed annually'], correct: 1, explanation: 'Any restrictions on normalcy activities must be documented and justified in the child\'s service plan. Restrictions cannot be blanket policies — they must be individualized.' },
      { id: 'e10q28', domain: 'Chapter 748', question: 'Life skills training (grocery shopping, cooking, money management) must begin for children at age:', options: ['12', '13', '14', '16'], correct: 2, explanation: 'Under Chapter 748, life skills training must begin for children age 14 and older. This includes grocery shopping, cooking, transportation, money management, and banking.' },
      { id: 'e10q29', domain: 'Chapter 748', question: 'Service plans for children age 13 and older must address:', options: ['College preparation only', 'Healthy relationships, personal boundaries, STDs, and reproduction', 'Employment and independent living only', 'Driver\'s education'], correct: 1, explanation: 'Under Chapter 748, service plans for children 13 and older must address healthy relationships, personal boundaries, STDs, and reproduction.' },
      { id: 'e10q30', domain: 'Chapter 748', question: 'During night-time sleeping hours, a caregiver who is asleep may care for how many children if at least one child in the group receives treatment services?', options: ['5', '10', '15', '24'], correct: 1, explanation: 'Under §748.1007(c)(1), a sleeping caregiver may care for 10 children if any child requires treatment services (16 if none do). An awake caregiver may care for 15 (treatment) or 24 (no treatment). Children under five count as two.' },
      { id: 'e10q31', domain: 'Chapter 748', question: 'Under Chapter 748, a young adult who turns 18 in a GRO may remain in care to transition to independence until the young adult\'s:', options: ['19th birthday', '21st birthday', '23rd birthday', '25th birthday'], correct: 2, explanation: '§748.1931(a): a young adult may remain in your care until the 23rd birthday to transition to independence, attend high school, complete your program, or stay with a minor sibling. See also §748.1933(c).' },
      { id: 'e10q32', domain: 'Chapter 748', question: 'A GRO bedroom of 220 square feet holds 4 children, none with primary medical needs. Is this compliant?', options: ['Yes — 40 sq ft per child is enough', 'No — 4 children need at least 240 sq ft (4 x 60)', 'Yes — 55 sq ft per child is fine', 'No — the maximum is 2 children per room'], correct: 1, explanation: '§748.3357(b)(2): a shared bedroom needs at least 60 sq ft per occupant, so 4 x 60 = 240 sq ft; 220 sq ft is short. No more than four occupants are allowed per bedroom, and floor space may not be averaged.' },
      { id: 'e10q33', domain: 'Chapter 748', question: 'Two unrelated 7-year-olds, a boy and a girl, share a bedroom. This is:', options: ['Compliant — they are the same age', 'Non-compliant — children 6 and older may not share a bedroom with the opposite gender unless an exception applies', 'Compliant if they are friends', 'Non-compliant only if parents object'], correct: 1, explanation: '§748.3363(a): children six or older must not share a bedroom with a child of the opposite gender unless an exception applies (siblings, a parent and child, or non-ambulatory children receiving treatment for primary medical needs). The service planning team must assess and document any exception (§748.3363(b)).' },
      { id: 'e10q34', domain: 'Chapter 748', question: 'A GRO has 16 children. The minimum number of toilets required is:', options: ['1', '2', '3', '4'], correct: 1, explanation: '16 children / 8 per toilet = 2 toilets minimum. The same ratio applies to sinks and bathtubs/showers. Toilets (§748.3393(b)(2)) and baths/showers (§748.3397(b)(1)) are counted separately by gender.' },
      { id: 'e10q35', domain: 'Chapter 748', question: 'During transport, ratio requirements for a group with treatment services children are:', options: ['1:8', '1:5', '1:10', 'No ratio required during transport'], correct: 1, explanation: 'Ratio requirements apply during transport. For groups with at least one child receiving treatment services, the 1:5 waking ratio applies.' },
      { id: 'e10q36', domain: 'Chapter 748', question: 'A caregiver uses pressure points to gain compliance from a child who is refusing to move. This is:', options: ['Allowed if the child poses a safety risk', 'Absolutely prohibited under Chapter 748', 'Allowed only by trained staff', 'Allowed as a last resort'], correct: 1, explanation: 'Pressure points are absolutely prohibited under §748.1119 and may never be used on any child under any circumstances — not even as a last resort or by trained staff.' },
      { id: 'e10q37', domain: 'Chapter 748', question: 'A caregiver denies a child dinner because the child refused to do chores. This is:', options: ['Acceptable as a natural consequence', 'Prohibited — denying food as punishment is a High Weight violation', 'Acceptable if the child is not hungry', 'Acceptable if the child can eat later'], correct: 1, explanation: 'Denying food that meets the child\'s nutritional requirements as punishment is a prohibited discipline technique under §748.2307 and is a High Weight violation.' },
      { id: 'e10q38', domain: 'Chapter 748', question: 'A caregiver makes a child run laps around the building as punishment for fighting. This is:', options: ['Acceptable — physical activity is healthy', 'Prohibited — unproductive work as punishment is not allowed', 'Acceptable if the child is physically able', 'Acceptable as a natural consequence of fighting'], correct: 1, explanation: 'Requiring unproductive physical activity (running laps, moving rocks, digging holes) as punishment is prohibited under §748.2303(b)(2)(A).' },
      { id: 'e10q39', domain: 'Chapter 748', question: 'A staff member uses a chemical spray to calm an agitated child. This is:', options: ['Allowed in emergency situations', 'Absolutely prohibited — chemical restraints are never allowed', 'Allowed only by medical staff', 'Allowed with supervisor approval'], correct: 1, explanation: 'Chemical restraints — using any substance to control behavior — are absolutely prohibited under §748.1119 and may never be used on any child.' },
      { id: 'e10q40', domain: 'Chapter 748', question: 'After an EBI (other than a short personal restraint), the operation must give the parent written notice:', options: ['Within 1 hour', 'Within 24 hours', 'As soon as possible, and no later than 72 hours', 'Within 7 days'], correct: 2, explanation: '§748.2857(a): written notice to the parent is due as soon as possible, but no later than 72 hours after the intervention was initiated. It is not required for short personal restraints (§748.2857(c)). Mechanical restraint also carries a 72-hour parent notice (§748.2701(e)).' },
      { id: 'e10q41', domain: 'Chapter 748', question: 'In a GRO with a capacity over 16 children, the observer for a prone or supine transitional hold must be:', options: ['The administrator', 'Trained in the risks of positional, compression and restraint asphyxia, and not involved in the restraint', 'Any child in care', 'A nurse only'], correct: 1, explanation: '§748.2605(b)(3): prone and supine transitional holds require an observer trained in asphyxia risks who is not involved in the restraint; GROs with a capacity of 16 or fewer children are exempt. Otherwise, a caregiver not restraining the child should monitor if available (§748.2601(b)).' },
      { id: 'e10q42', domain: 'Chapter 748', question: 'EBI must be discontinued:', options: ['After 15 minutes regardless of the situation', 'As soon as the danger has passed', 'When the child agrees to comply', 'After the supervisor approves discontinuation'], correct: 1, explanation: 'EBI must be discontinued as soon as the danger has passed. It may not continue beyond what is necessary to ensure safety.' },
      { id: 'e10q43', domain: 'Chapter 748', question: 'A 15-year-old in your GRO wants to attend her school prom. Under the RPPS, you should:', options: ['Deny — prom is not in the service plan', 'Apply the RPPS: a reasonable parent would allow a 15-year-old to attend prom — support the request', 'Require a 30-day advance notice to the caseworker', 'Allow only if the child has no behavioral incidents in the past 90 days'], correct: 1, explanation: 'Attending prom is a normal childhood activity. The RPPS asks what a reasonable parent would allow — a reasonable parent would support a 15-year-old attending prom. Document the decision.' },
      { id: 'e10q44', domain: 'Chapter 748', question: 'Service plans for children age 16 and older must address:', options: ['College entrance exams only', 'Preparation for independent living and employment', 'Driver\'s education only', 'Healthy relationships only'], correct: 1, explanation: 'Under Chapter 748, service plans for children 16 and older must address preparation for independent living and employment.' },
      { id: 'e10q45', domain: 'Chapter 748', question: 'A prone (face-down) restraint that restricts breathing is:', options: ['Allowed in extreme emergencies', 'Absolutely prohibited under Chapter 748', 'Allowed only by trained staff', 'Allowed for children over 12'], correct: 1, explanation: 'Any restraint technique that restricts breathing — including prone restraints that restrict breathing — is absolutely prohibited under §748.2605. Prone and supine holds are allowed only as a transitional hold of no more than 1 minute, as a last resort, with a trained observer (GROs over 16 children) — §748.2605(b).' },
      { id: 'e10q46', domain: 'Chapter 748', question: 'A child\'s personal belongings may be confiscated as punishment:', options: ['Yes, if the item was used in a behavioral incident', 'No — unreasonable removal of personal items and denying basic child rights as punishment are prohibited', 'Yes, temporarily for up to 24 hours', 'Yes, with supervisor approval'], correct: 1, explanation: 'Children have the right to be free of unreasonable searches and unreasonable removal of personal items (§748.1101(b)(3)(K)), and denying basic child rights as discipline or punishment is prohibited (§748.2307(13)).' },
      { id: 'e10q47', domain: 'Chapter 748', question: 'Clothing may be withheld from a child as punishment:', options: ['Yes, if the child damaged the clothing', 'No — clothing may never be withheld as punishment', 'Yes, temporarily for up to 12 hours', 'Yes, with parental consent'], correct: 1, explanation: 'Children have a right to comfortable, weather-appropriate clothing (§748.1101(b)(3)(G)-(H)), and denying basic child rights as discipline or punishment is prohibited (§748.2307(13)).' },
      { id: 'e10q48', domain: 'Chapter 748', question: 'During waking hours, a group of 5 children includes one child receiving treatment services and one 3-year-old. How many caregivers are required?', options: ['1', '2', '3', '4'], correct: 1, explanation: '§748.1003(a): the ratio is 1:5 when any child needs treatment services, and children under five count as two. The 3-year-old counts as two, so the group counts as 6 and requires 2 caregivers. The ratio also applies off-site (§748.1017(a)).' },
      { id: 'e10q49', domain: 'Chapter 748', question: 'A staff member makes a child stand in the corner facing the wall for 45 minutes as punishment. This is:', options: ['Acceptable as a time-out technique', 'Prohibited — requiring a child to maintain a physical position for extended periods is not allowed', 'Acceptable if the child is not in distress', 'Acceptable for children over 10'], correct: 1, explanation: 'Requiring a child to maintain a physical position for extended periods is a prohibited discipline technique under §748.2307.' },
      { id: 'e10q50', domain: 'Chapter 748', question: 'A staff member tells a child "if you keep acting like this, you\'ll be moved to a different placement." This is:', options: ['Acceptable as a warning about natural consequences', 'Prohibited — threatening loss of placement is not allowed as a discipline technique', 'Acceptable if the threat is realistic', 'Acceptable with supervisor approval'], correct: 1, explanation: 'Threatening loss of placement is a prohibited discipline technique under §748.2307. It creates fear and instability that can re-traumatize children in care.' },
      { id: 'e10q51', domain: 'Chapter 748', question: 'What is the maximum length of a personal restraint (other than a transitional hold) for a child of any age?', options: ['1 minute', '15 minutes', '30 minutes', '1 hour'], correct: 2, explanation: 'Under §748.2801(2), a personal restraint may not exceed 30 minutes for a child of any age, and a prone or supine transitional hold may not exceed 1 minute. A personal restraint cannot be extended (§748.2805).' },
      { id: 'e10q52', domain: 'Chapter 748', question: 'The supervisor of caregivers involved in an emergency behavior intervention must review and document the use of the intervention within:', options: ['24 hours', '48 hours', '72 hours', '7 days'], correct: 2, explanation: 'Under §748.2851(d) and §748.2855(b), the supervisor must review the intervention and document the review within 72 hours. Caregiver documentation is due within 24 hours (§748.2855(a)).' },
      { id: 'e10q53', domain: 'Chapter 748', question: 'Each employee who drives children away from the operation must be at least what age (excluding the exception for children in care)?', options: ['18', '19', '21', '25'], correct: 2, explanation: 'Under §748.4003(1)(A), each driver must be at least 21, covered by automobile insurance, and hold a license for the vehicle type. A child in care may transport other children only with a valid license, insurance, and service planning team permission (§748.4005).' },
      { id: 'e10q54', domain: 'Chapter 748', question: 'Which child must NOT be assigned a top bunk?', options: ['A child under six years old', 'A child over ten', 'A child who wears glasses', 'A child new to the operation'], correct: 0, explanation: 'Under §748.3369(b), a child under six, a non-ambulatory child, or a child subject to seizures or other conditions needing greater supervision must not use a top bunk. Bunk beds must be double-deck only (§748.3369(a)); triple-deck beds are not allowed (§748.3367).' },
    ],
  },
  {
    id: 'exam-11',
    number: 11,
    title: 'Ch. 748 — Admission, Discharge & Records Mastery',
    description: '55 questions covering Chapter 748 admission requirements, medical/dental timelines, discharge planning, record retention, operation notifications, and mixed Chapter 748 mastery.',
    questions: [
      { id: 'e11q1', domain: 'Chapter 748', question: 'For a non-emergency admission to a GRO, the admission assessment must be completed:', options: ['Within 24 hours of admission', 'Within 72 hours of admission', 'Prior to admission', 'Within 40 days of admission'], correct: 2, explanation: 'For a non-emergency admission, the admission assessment must be completed PRIOR TO admission. For emergency admissions, all requirements must be completed within 40 days.' },
      { id: 'e11q2', domain: 'Chapter 748', question: 'For an emergency admission, all admission requirements must be completed within:', options: ['24 hours', '72 hours', '30 days', '40 days'], correct: 3, explanation: 'Under §748.1269, for an emergency admission, all requirements for the admission assessment must be completed within 40 days from the date of admission.' },
      { id: 'e11q3', domain: 'Chapter 748', question: 'A medical examination for a newly admitted child must be completed within:', options: ['7 days of admission', '14 days of admission', '30 days of admission', '90 days of admission'], correct: 2, explanation: 'Under §748.1223(a), a medical exam by a health-care professional is required within 30 days after admission. It is not required if you have documentation of a medical exam within the past year (including a DFPS health passport). The 7-days-before/3-days-after window applies only to children with primary medical needs (§748.1223(b)).' },
      { id: 'e11q4', domain: 'Chapter 748', question: 'A dental appointment for a newly admitted child must be SCHEDULED within:', options: ['7 days', '14 days', '30 days', '60 days'], correct: 2, explanation: 'The dental appointment must be SCHEDULED within 30 days of admission. The actual dental exam must be COMPLETED within 90 days. No exam is required if documentation shows a dental exam within the past year (§748.1225(b)).' },
      { id: 'e11q5', domain: 'Chapter 748', question: 'A dental exam for a newly admitted child must be COMPLETED within:', options: ['30 days', '60 days', '90 days', '120 days'], correct: 2, explanation: 'The dental appointment must be scheduled within 30 days, but the actual dental exam must be COMPLETED within 90 days of admission. No exam is required if documentation shows a dental exam within the past year (§748.1225(b)).' },
      { id: 'e11q6', domain: 'Chapter 748', question: 'A newly admitted child who is 5 years old or older must receive orientation to the operation within:', options: ['24 hours', '3 days', '7 days', '30 days'], correct: 2, explanation: 'Under §748.1209(a), you must provide orientation within seven days of admission to each newly admitted child five years old or older, geared to the child\'s intellectual level.' },
      { id: 'e11q7', domain: 'Chapter 748', question: 'For a child with primary medical needs, the medical examination must be completed within:', options: ['7 days before or 3 days after admission', '14 days of admission', '30 days of admission', '40 days of admission'], correct: 0, explanation: 'For children with primary medical needs, the medical examination must be completed within 7 days before or 3 days after admission — a tighter window than the standard 30-day requirement.' },
      { id: 'e11q8', domain: 'Chapter 748', question: 'Required immunizations for a newly admitted child must be completed:', options: ['By the date of admission (with exceptions)', 'Within 7 days of admission', 'Within 14 days of admission', 'Within 30 days for every child'], correct: 0, explanation: 'Under §748.1539(c), required immunizations must be completed by the date of admission unless the child is exempt (§748.1541). A homeless child or a child in foster care may be admitted temporarily for 30 days if acceptable evidence of immunization is not available; refer the child to a health-care professional immediately.' },
      { id: 'e11q9', domain: 'Chapter 748', question: 'Which statement about vision and hearing screening of admitted children is correct?', options: ['Each child must be screened under Health and Safety Code Chapter 36, and a professional exam is required if problems are detected', 'Screening is required only if a parent requests it', 'Screening is required only for children under 12', 'Screening must be done by the operation\'s administrator'], correct: 0, explanation: 'Under §748.1545, each admitted child must be screened for vision and hearing problems per Health and Safety Code Chapter 36, and a professional exam is required if problems are detected. Keep the screening results (or another allowed record) in the child\'s record (§748.1545(b)); DFPS health-passport results suffice.' },
      { id: 'e11q10', domain: 'Chapter 748', question: 'For a child receiving treatment services admitted on an emergency basis to a GRO (not RTC), the required psychiatric/psychological evaluation must be completed within:', options: ['10 days', '20 days', '30 days', '40 days'], correct: 2, explanation: 'Under §748.1269(2), in an emergency admission of a child receiving treatment services, the child must not continue in care more than 30 days after admission (10 days for a residential treatment center) unless the required psychiatric evaluation, psychological evaluation, psychosocial assessment, or medical evaluation (§748.1219) has been received and indicates manifestations of the disorder requiring treatment.' },
      { id: 'e11q11', domain: 'Chapter 748', question: 'The admission assessment for a non-emergency admission must include all of the following EXCEPT:', options: ['Child\'s trauma history', 'Current physical and mental health status', 'The child\'s preferred placement location', 'Educational history and current status'], correct: 2, explanation: 'The admission assessment must include trauma history, physical/mental health status, educational history, social history, strengths, and immediate needs. The child\'s preferred placement location is not a required component.' },
      { id: 'e11q12', domain: 'Chapter 748', question: 'Child records must be retained for how long after a child\'s discharge from a GRO?', options: ['1 year', '2 years', '3 years', '5 years'], correct: 1, explanation: 'Under Chapter 748, child records must be retained for 2 years after the child\'s discharge, or until any investigation involving the child is resolved, whichever is longer. (§748.433: two years from the date of discharge, or until any investigation involving the child is resolved, whichever is longer.)' },
      { id: 'e11q13', domain: 'Chapter 748', question: 'Personnel records must be retained for how long after an employee\'s last day of employment?', options: ['6 months', '1 year (or until investigation resolved)', '2 years', '3 years'], correct: 1, explanation: 'Under §748.431, personnel records must be maintained for 1 year after an employee\'s last day of employment, or until any investigation involving the employee is resolved, whichever is longer.' },
      { id: 'e11q14', domain: 'Chapter 748', question: 'Incident reports must be kept on file for:', options: ['1 year', '2 years', '3 years', '5 years'], correct: 1, explanation: 'Under Chapter 748, incident reports must be kept on file for 2 years. (§748.315)' },
      { id: 'e11q15', domain: 'Chapter 748', question: 'The annual summary log for unauthorized absences must be retained for:', options: ['1 year', '2 years', '3 years', '5 years'], correct: 3, explanation: 'Under §748.453(b), the annual summary log for unauthorized absences must be retained for 5 years.' },
      { id: 'e11q16', domain: 'Chapter 748', question: 'Medication records must be retained for:', options: ['1 year after discharge', '2 years after discharge', '3 years after discharge', '5 years after discharge'], correct: 1, explanation: 'The cumulative medication record (§748.2151) is part of the child\'s record, which must be maintained for two years after discharge or until any investigation involving the child is resolved, whichever is longer (§748.433).' },
      { id: 'e11q17', domain: 'Chapter 748', question: 'You must notify Licensing of an administrator vacancy within:', options: ['24 hours', '2 days', '7 days', '15 days'], correct: 1, explanation: 'Under §748.153, you must notify Licensing as soon as possible, but no later than 2 days after your child-care administrator changes or the position becomes vacant.' },
      { id: 'e11q18', domain: 'Chapter 748', question: 'You must notify Licensing of a policy change at least how many days before it takes effect?', options: ['2 days', '7 days', '15 days', '30 days'], correct: 2, explanation: 'Under Chapter 748, Licensing must be notified at least 15 days before any policy change takes effect.' },
      { id: 'e11q19', domain: 'Chapter 748', question: 'You must notify Licensing of a location change at least how many days before the move?', options: ['2 days', '7 days', '15 days', '30 days'], correct: 3, explanation: 'Under Chapter 748, Licensing must be notified at least 30 days before a location change.' },
      { id: 'e11q20', domain: 'Chapter 748', question: 'When a child is discharged, the information that must be provided to the next placement or caregiver includes:', options: ['Only the discharge summary', 'The discharge summary, 60 days of progress notes, unresolved incidents or investigations, and assessments or evaluations', 'Only medical records', 'Only educational records'], correct: 1, explanation: 'Under §748.1439(b), copies provided to the next placement or caregiver must include a written discharge summary; background information including progress notes for the past 60 days; any unresolved incidents or investigations; and assessments or evaluations you performed (including the admission assessment).' },
      { id: 'e11q21', domain: 'Chapter 748', question: 'If legal consent to release information is obtained at discharge, the information must be given to the receiving placement or caregiver within:', options: ['24 hours', '2 days', '7 days', '15 days'], correct: 3, explanation: 'Under §748.1439(a), you must attempt to obtain legal consent on or before discharge (and document the attempt if refused). If consent is obtained, the information must be provided within 15 days of the date of discharge.' },
      { id: 'e11q22', domain: 'Chapter 748', question: 'A child\'s service plan must include plans for experiential life-skills training to improve the transition to independent living beginning at age:', options: ['12', '14', '16', '18'], correct: 1, explanation: 'Under §748.1337(b)(1)(F), the service plan for a child 14 or older must include plans for caregivers to assist the child in obtaining experiential life-skills training (such as grocery shopping, meal preparation, public transportation, and money management). For children 16 and older, §748.1337(b)(1)(G) adds preparation for independent living, including employment opportunities.' },
      { id: 'e11q23', domain: 'Chapter 748', question: 'Child orientation must include information on how to:', options: ['Make complaints to outside agencies and contact parties to the child\'s case', 'File a lawsuit against the operation', 'Apply for a driver\'s license', 'Request a transfer to another operation'], correct: 0, explanation: 'Under §748.1209(c), orientation must include how to make complaints to outside agencies and how to contact parties to the child\'s case (caseworker, attorney ad litem, guardian ad litem, CASA). Internal grievance procedures are also covered in orientation (§748.1209(b)(13)).' },
      { id: 'e11q24', domain: 'Chapter 748', question: 'The operation\'s permit must be:', options: ['Kept in the administrator\'s office', 'Posted in a prominent and publicly accessible place', 'Submitted to CCR annually', 'Kept in the child\'s file'], correct: 1, explanation: 'Under §748.191, the permit must be posted in a prominent, publicly accessible place where employees, children, parents and others can easily view it at all times. Also post the Licensing notice "Keeping Children Safe" and the emergency and evacuation relocation plans in each building used by children.' },
      { id: 'e11q25', domain: 'Chapter 748', question: 'A provisional license holder may serve:', options: ['Up to 2 operations', 'Only 1 operation', 'Up to 3 operations if they are contiguous', 'Any number of operations'], correct: 1, explanation: 'A provisional license holder may only serve ONE operation. A regular license holder may serve two operations under specific conditions.' },
      { id: 'e11q26', domain: 'Chapter 748', question: 'An administrator CAN serve two residential operations if all of the following are true EXCEPT:', options: ['Both operations are in good standing', 'The operations are contiguous', 'The administrator has a provisional license', 'The size and complexity are manageable'], correct: 2, explanation: 'A provisional license holder may only serve ONE operation. To serve two operations, the administrator must have a regular (non-provisional) license, both operations must be in good standing, and the operations must be contiguous.' },
      { id: 'e11q27', domain: 'Chapter 748', question: 'A preliminary service plan must be completed within 72 hours of admission. For an emergency admission, this timeline:', options: ['Is extended to 40 days', 'Is extended to 7 days', 'Remains 72 hours — the preliminary plan is still required within 72 hours', 'Is waived entirely'], correct: 2, explanation: 'Even for emergency admissions, the preliminary service plan must still be completed within 72 hours of admission. Only the full admission assessment requirements are extended to 40 days.' },
      { id: 'e11q28', domain: 'Chapter 748', question: 'A child\'s service plan must be implemented no later than how many days after the scheduled service planning meeting?', options: ['7 days', '10 days', '15 days', '30 days'], correct: 2, explanation: 'Under §748.1351, a service plan must be implemented no later than 15 days after the date of the scheduled service planning meeting.' },
      { id: 'e11q29', domain: 'Chapter 748', question: 'Parents must receive advance notice of an initial service plan meeting at least:', options: ['3 days before', '1 week before', '2 weeks before', '30 days before'], correct: 2, explanation: 'Under §748.1341, the child\'s parent must have at least two weeks advance notice of the initial service plan meeting.' },
      { id: 'e11q30', domain: 'Chapter 748', question: 'A child in your GRO has been missing for 7 hours. She is 15 years old and has no history of trafficking. You have already notified law enforcement and Licensing. What else must you do?', options: ['Nothing more until she returns', 'Notify her parents/guardians', 'File a missing persons report with the FBI', 'Notify the governing body'], correct: 1, explanation: 'For an unauthorized absence of a child 13 or older, you must notify all parties (law enforcement, Licensing, AND parents) no later than 6 hours from when the absence was discovered. Parents must be notified.' },
      { id: 'e11q31', domain: 'Chapter 748', question: 'After a child returns from an unauthorized absence, a debrief must occur within:', options: ['2 hours of return', '12 hours of return', '24 hours of return', '48 hours of return'], correct: 2, explanation: 'Under §748.455, the debriefing must occur as soon as possible, but no later than 24 hours after the child\'s return from an unauthorized absence.' },
      { id: 'e11q32', domain: 'Chapter 748', question: 'If a child has 3 unauthorized absences within a 60-day timeframe, a triggered review must occur within:', options: ['7 days', '14 days', '30 days', '60 days'], correct: 2, explanation: 'Under §748.457, a triggered review must occur as soon as possible, but no later than 30 days after the child\'s third unauthorized absence within a 60-day timeframe.' },
      { id: 'e11q33', domain: 'Chapter 748', question: 'An overall operation evaluation for unauthorized absences must be conducted every:', options: ['3 months', '6 months', '12 months', '2 years'], correct: 1, explanation: 'Under §748.463, every 6 months you must conduct an overall operation evaluation for unauthorized absences that have occurred at your operation during that time period.' },
      { id: 'e11q34', domain: 'Chapter 748', question: 'A child death must be reported to law enforcement within:', options: ['30 minutes', '1 hour', '2 hours', '24 hours'], correct: 1, explanation: 'Under §748.303, a child death must be reported to law enforcement immediately, but no later than 1 hour after the child\'s death.' },
      { id: 'e11q35', domain: 'Chapter 748', question: 'A child death must be reported to Licensing and parents within:', options: ['1 hour', '2 hours', '4 hours', '24 hours'], correct: 1, explanation: 'Under §748.303, a child death must be reported to Licensing and parents as soon as possible, but no later than 2 hours after the child\'s death.' },
      { id: 'e11q36', domain: 'Chapter 748', question: 'A substantial physical injury must be reported to Licensing within:', options: ['1 hour', '2 hours', '12 hours', '24 hours'], correct: 3, explanation: 'Under §748.303, a substantial physical injury must be reported to Licensing as soon as possible, but no later than 24 hours after the incident.' },
      { id: 'e11q37', domain: 'Chapter 748', question: 'All serious incident reports must be made to:', options: ['Your CCR licensing representative directly', 'The Texas Abuse and Neglect Hotline', 'The local police department', 'The DFPS regional office'], correct: 1, explanation: 'Under §748.309, all serious incident reports must be made directly to the Texas Abuse and Neglect Hotline.' },
      { id: 'e11q38', domain: 'Chapter 748', question: 'A suicide attempt must be reported to Licensing:', options: ['Within 1 hour', 'Within 2 hours', 'As soon as you become aware of the incident', 'Within 24 hours'], correct: 2, explanation: 'Under §748.303, a suicide attempt must be reported to Licensing as soon as you become aware of the incident.' },
      { id: 'e11q39', domain: 'Chapter 748', question: 'Schedule II controlled substances must be stored under:', options: ['A single lock', 'Double lock in a separate container', 'A locked refrigerator', 'The administrator\'s personal custody'], correct: 1, explanation: 'Under §748.2101, Schedule II controlled substances must be stored under double lock in a separate container — for example, a lock on the cabinet AND a lock on the closet door.' },
      { id: 'e11q40', domain: 'Chapter 748', question: 'A medication administration record must be updated within how long of administering medication (non-cottage home)?', options: ['30 minutes', '1 hour', '2 hours', '24 hours'], correct: 2, explanation: 'Under §748.2151, the cumulative medication record must be updated within 2 hours of administering medication (or within 24 hours for cottage homes).' },
      { id: 'e11q41', domain: 'Chapter 748', question: 'Prescription medication must be administered within how long of preparation?', options: ['30 minutes', '1 hour', '2 hours', '4 hours'], correct: 1, explanation: 'Under §748.2003, each child\'s medication must be administered within 1 hour of preparation.' },
      { id: 'e11q42', domain: 'Chapter 748', question: 'A medication error must be documented within:', options: ['1 hour', '2 hours', '12 hours', '24 hours'], correct: 3, explanation: 'Under §748.2203, all medication errors must be documented within 24 hours, including the time/date of the error, the error itself, and the health-care professional\'s recommendations.' },
      { id: 'e11q43', domain: 'Chapter 748', question: 'The effectiveness of a psychotropic medication must be evaluated at least:', options: ['Monthly', 'Every 2 months', 'Quarterly (every 3 months)', 'Every 6 months'], correct: 2, explanation: 'Under §748.2261, the prescribing professional must evaluate the effectiveness of psychotropic medication at least quarterly (every 3 months).' },
      { id: 'e11q44', domain: 'Chapter 748', question: 'A caregiver must be at least 21 years old if:', options: ['They work in a residential treatment center', 'At least one child in the group they serve is 13 years old or older', 'They administer medication', 'They are the only caregiver on duty'], correct: 1, explanation: 'Under §748.681, a caregiver must be at least 21 years old if at least one child in the group they serve is 13 years old or older. If all children are under 13, the minimum age is 18.' },
      { id: 'e11q45', domain: 'Chapter 748', question: 'How many hours of general pre-service training must a caregiver complete before being counted in the child/caregiver ratio?', options: ['2 hours', '4 hours', '8 hours', '16 hours'], correct: 1, explanation: 'Under §748.863, a caregiver must complete at least 4 hours of general pre-service training before being counted in the ratio. The remaining 4 hours (total 8) must be completed within 30 days.' },
      { id: 'e11q46', domain: 'Chapter 748', question: 'The maximum number of annual training hours that may come from self-study training is:', options: ['1 hour', '3 hours', '5 hours', '10 hours'], correct: 1, explanation: 'Under §748.937, no more than 3 hours of the required annual training hours may come from self-study training.' },
      { id: 'e11q47', domain: 'Chapter 748', question: 'EBI annual training for caregivers at treatment operations must be completed every:', options: ['3 months', '6 months', '12 months', '2 years'], correct: 1, explanation: 'Under §748.936, caregivers at operations providing treatment services must complete EBI training every 6 months.' },
      { id: 'e11q48', domain: 'Chapter 748', question: 'A GRO administrator must be:', options: ['A part-time employee with an LCCA license', 'A full-time employee with an LCCA license', 'A full-time employee with a master\'s degree', 'Any licensed professional designated by the governing body'], correct: 1, explanation: 'Under §748.531, a child-care administrator must be a Licensed Child-Care Administrator AND a full-time employee of the operation.' },
      { id: 'e11q49', domain: 'Chapter 748', question: 'If the administrator position becomes vacant with NO backup administrator, the operation has how long to obtain a licensed administrator before CCR can cite them?', options: ['30 days', '45 days', '60 days', '90 days'], correct: 2, explanation: 'Under §748.154, if there is no backup administrator, the operation has 60 days from the date the position becomes vacant to obtain a licensed child-care administrator.' },
      { id: 'e11q50', domain: 'Chapter 748', question: 'Sibling contact restrictions must be re-evaluated every:', options: ['30 days', '60 days', '90 days', '180 days'], correct: 1, explanation: 'Under §748.1109, restrictions on sibling contact must be re-evaluated every 60 days by a professional level service provider.' },
      { id: 'e11q51', domain: 'Chapter 748', question: 'For a non-emergency discharge, a child must be informed at least how many days before the discharge, absent written justification?', options: ['1 day', '2 days', '4 days', '14 days'], correct: 2, explanation: 'Under §748.1433(d) and (e), you must inform the child of a non-emergency discharge or transfer at least four days before it occurs, unless an authorized person puts the justification for no notice in writing, signed and dated, in the child\'s record.' },
      { id: 'e11q52', domain: 'Chapter 748', question: 'A child\'s personal money held by the operation must be given or sent to the child, parent, or next placement within what time after discharge?', options: ['24 hours', '7 days', '15 days', '30 days'], correct: 3, explanation: 'Under §748.161(b), you must give or send the child\'s money to the child, parent, or next placement within 30 days of the child\'s discharge.' },
      { id: 'e11q53', domain: 'Chapter 748', question: 'When discharging or transferring a child who is an immediate danger to self or others, who must accompany the child to the receiving placement?', options: ['No one; the receiving placement picks the child up', 'An employee of the operation, unless the parent or law enforcement transports the child', 'Any adult resident of the operation', 'Only the licensed child-care administrator'], correct: 1, explanation: 'Under §748.1435, an employee of your operation must accompany the child to the receiving operation, agency or person unless the child\'s parent or law enforcement transports the child.' },
      { id: 'e11q54', domain: 'Chapter 748', question: 'A child is re-admitted 8 months after being discharged from your operation. For admission documentation you:', options: ['Need nothing; the old file is enough', 'Must complete it as if the child was never in care, or may update the previous documentation since the discharge was within 12 months', 'Must always complete a brand-new admission assessment', 'May update it only if discharged within the past 30 days'], correct: 1, explanation: 'Under §748.1227, for re-admission you must complete the admission documentation as if the child was never in your care; for children discharged within the last 12 months, you may update the previous admission documentation.' },
      { id: 'e11q55', domain: 'Chapter 748', question: 'Which programs may NOT accept emergency admissions?', options: ['Residential treatment centers and emergency care programs', 'Transitional living programs and therapeutic camp programs', 'Child-care services programs only', 'Any program serving children 13 or older'], correct: 1, explanation: 'Under §748.1261, neither a transitional living program nor a therapeutic camp program may accept emergency admissions. All other programs may.' },
    ],
  },
];

export const lccaPracticeExams: PracticeExam[] = [...lccaGroExamsA, ...lccaGroExamsB, ...lccaGroExamsC, ...lccaExams9to11].sort((a, b) => a.number - b.number);
